// ---------- colours ----------
function colourFor(i, offset) {
  const h = (offset + i * 137.508) % 360;           // golden angle: neighbours in the list always differ
  const l = [58, 48, 68][i % 3];
  const s = [62, 72, 55][Math.floor(i / 3) % 3];
  return "hsl(" + h.toFixed(1) + "," + s + "%," + l + "%)";
}
const STATES = STATES_DATA.features.slice().sort((a, b) => a.properties.n.localeCompare(b.properties.n));
STATES.forEach((f, i) => (f.properties.color = colourFor(i, 10)));
const districtsOf = {};
DISTRICTS_DATA.features.forEach(f => (districtsOf[f.properties.s] = districtsOf[f.properties.s] || []).push(f));
Object.keys(districtsOf).forEach((s, k) => {
  districtsOf[s].sort((a, b) => a.properties.n.localeCompare(b.properties.n));
  districtsOf[s].forEach((f, i) => (f.properties.color = colourFor(i, 40 + k * 23)));
});

// ---------- map ----------
const INDIA_BOUNDS = L.latLngBounds([6, 68], [37.5, 97.5]);
const map = L.map("map", { zoomSnap: 0.25, minZoom: 4 });
L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png", {
  subdomains: "abcd", maxZoom: 19,
  attribution: "&copy; OpenStreetMap contributors &copy; CARTO"
}).addTo(map);
map.createPane("borders"); map.getPane("borders").style.zIndex = 420; map.getPane("borders").style.pointerEvents = "none";
map.createPane("labels");  map.getPane("labels").style.zIndex = 450;  map.getPane("labels").style.pointerEvents = "none";

let selected = null;            // name of the selected state, or null for the India view
let districtLayer = null;       // districts of the selected state
let outlineLayer = null;        // thick outline of the selected state

// ---------- states ----------
function stateStyle(f) {
  const n = f.properties.n;
  if (!selected) return { color: "#fff", weight: 1.2, fillColor: f.properties.color, fillOpacity: 0.85 };
  if (n === selected) return { color: "#fff", weight: 0, fillOpacity: 0 };
  return { color: "#fff", weight: 1, fillColor: "#cfd6dd", fillOpacity: 0.7 };
}
const stateLayers = {};
const statesLayer = L.geoJSON({ type: "FeatureCollection", features: STATES }, {
  style: stateStyle,
  onEachFeature: (f, l) => {
    const n = f.properties.n;
    stateLayers[n] = l;
    l.bindTooltip(n, { sticky: true });
    l.on("click", () => { if (n !== selected) selectState(n); });
    l.on("mouseover", () => l.setStyle({ weight: 2.5, fillColor: f.properties.color, fillOpacity: 0.95 }));
    l.on("mouseout", () => statesLayer.resetStyle(l));
  }
}).addTo(map);

function selectState(name) {
  selected = name;
  statesLayer.setStyle(stateStyle);
  if (districtLayer) map.removeLayer(districtLayer);
  if (outlineLayer) map.removeLayer(outlineLayer);

  const feats = districtsOf[name] || [];
  districtLayer = L.geoJSON({ type: "FeatureCollection", features: feats }, {
    style: f => ({ color: "#fff", weight: 1, fillColor: f.properties.color, fillOpacity: 0.85 }),
    onEachFeature: (f, l) => {
      l.bindTooltip(f.properties.n + ", " + name, { sticky: true });
      l.on("mouseover", () => l.setStyle({ weight: 2.5, fillOpacity: 1 }));
      l.on("mouseout", () => districtLayer.resetStyle(l));
    }
  }).addTo(map);
  outlineLayer = L.geoJSON(stateLayers[name].feature, {
    pane: "borders", interactive: false, style: { color: "#1d2733", weight: 2.5, fill: false }
  }).addTo(map);

  map.fitBounds(stateLayers[name].getBounds(), { padding: [40, 40] });
  updateUI();
  refreshLabels();
}

function resetView() {
  selected = null;
  if (districtLayer) { map.removeLayer(districtLayer); districtLayer = null; }
  if (outlineLayer) { map.removeLayer(outlineLayer); outlineLayer = null; }
  statesLayer.setStyle(stateStyle);
  map.fitBounds(INDIA_BOUNDS, { padding: [10, 10] });
  updateUI();
  refreshLabels();
}

// ---------- labels: a name is shown only when its area is wide enough on screen ----------
function bboxOf(f) {
  let w = 999, s = 999, e = -999, n = -999;
  f.geometry.coordinates.forEach(poly => poly[0].forEach(p => {
    if (p[0] < w) w = p[0]; if (p[0] > e) e = p[0];
    if (p[1] < s) s = p[1]; if (p[1] > n) n = p[1];
  }));
  return L.latLngBounds([s, w], [n, e]);
}
function makeLabel(f, cls, px) {
  const m = L.marker([f.properties.c[1], f.properties.c[0]], {
    pane: "labels", interactive: false, keyboard: false,
    icon: L.divIcon({ className: "lbl " + cls, html: f.properties.n, iconSize: null })
  });
  m._b = bboxOf(f);
  m._w = f.properties.n.length * px * 0.75;      // approx. text width in pixels
  m._state = f.properties.n;
  return m;
}
const stateLabels = STATES.map(f => makeLabel(f, "lbl-state", 7));
const districtLabels = {};                       // built per state on first use
const labelGroup = L.layerGroup().addTo(map);

function refreshLabels() {
  labelGroup.clearLayers();
  const view = map.getBounds().pad(0.1);
  const fits = m => {
    const a = map.latLngToContainerPoint(m._b.getNorthWest()), b = map.latLngToContainerPoint(m._b.getSouthEast());
    return b.x - a.x >= m._w;
  };
  stateLabels.forEach(m => {
    if (m._state === selected) return;
    if (view.contains(m.getLatLng()) && fits(m)) {
      labelGroup.addLayer(m);
      m.getElement().classList.toggle("lbl-dim", !!selected);   // other states are greyed once one is selected
    }
  });
  if (selected) {
    if (!districtLabels[selected])
      districtLabels[selected] = (districtsOf[selected] || []).map(f => makeLabel(f, "lbl-district", 6));
    districtLabels[selected].forEach(m => {
      if (view.contains(m.getLatLng()) && fits(m)) labelGroup.addLayer(m);
    });
  }
}
map.on("zoomend moveend", refreshLabels);

// ---------- UI ----------
const css = document.createElement("style");
css.textContent =
  ".lbl{white-space:nowrap;text-align:center;transform:translate(-50%,-50%);width:auto!important;height:auto!important;" +
  "color:#111;text-shadow:-1px -1px 0 #fff,1px -1px 0 #fff,-1px 1px 0 #fff,1px 1px 0 #fff,0 0 4px #fff}" +
  ".lbl-state{font:700 12px sans-serif;letter-spacing:.3px}" +
  ".lbl-dim{color:#6b7280;font-weight:600}" +
  ".lbl-district{font:600 11px sans-serif}" +
  ".panel{background:#fff;padding:8px 12px;border-radius:6px;font:13px sans-serif;box-shadow:0 1px 4px rgba(0,0,0,.3)}" +
  ".panel button{font:600 13px sans-serif;padding:6px 10px;border:0;border-radius:6px;background:#1d2733;color:#fff;cursor:pointer}";
document.head.appendChild(css);

const info = L.control({ position: "topright" });
info.onAdd = () => (info._div = L.DomUtil.create("div", "panel"));
info.addTo(map);

const back = L.control({ position: "topleft" });
back.onAdd = () => {
  const d = L.DomUtil.create("div", "panel");
  d.style.padding = "4px";
  d.innerHTML = "<button>&larr; All India</button>";
  L.DomEvent.disableClickPropagation(d);
  d.querySelector("button").addEventListener("click", resetView);
  back._div = d;
  return d;
};
back.addTo(map);

function updateUI() {
  back._div.style.display = selected ? "block" : "none";
  info._div.innerHTML = selected
    ? "<b>" + selected + "</b><br>" + (districtsOf[selected] || []).length + " districts &middot; click another state to switch"
    : "<b>India</b><br>" + STATES.length + " states &amp; UTs &middot; click a state to see its districts";
}
document.addEventListener("keydown", e => { if (e.key === "Escape" && selected) resetView(); });

map.setView([22.5, 80], 5);   // safe starting view so it's never blank
window.addEventListener("load", () => {
  map.invalidateSize();       // tell Leaflet the real size of the map box
  resetView();                // now fit all of India correctly
});
